#include <testlib.h>

int main(int argc, char** argv) {
    registerTestlibCmd(argc, argv);

    const long long n = inf.readLong();
    const long long x = ouf.readLong();

    if (n < 100 || n > 995) {
        quitf(_fail, "input is outside the stated range");
    }
    if (x <= n || x >= 1000 || x % 6 != 0) {
        quitf(_wa, "the output is not a valid construction");
    }
    if (!ouf.seekEof()) {
        quitf(_pe, "extra output");
    }

    quitf(_ok, "valid construction");
}
